CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PersonalProfile" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"displayName" TEXT NOT NULL DEFAULT '',"values" TEXT NOT NULL DEFAULT '',"direction" TEXT NOT NULL DEFAULT '',"currentFocus" TEXT NOT NULL DEFAULT '',"supportStyle" TEXT NOT NULL DEFAULT '',"version" INTEGER NOT NULL DEFAULT 1,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PersonalProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProfileVersion" ("id" TEXT NOT NULL,"profileId" TEXT NOT NULL,"version" INTEGER NOT NULL,"snapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProfileVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "World" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"slug" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"intention" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "World_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Action" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"worldId" TEXT,"title" TEXT NOT NULL,"notes" TEXT NOT NULL DEFAULT '',"priority" TEXT NOT NULL DEFAULT 'normal',"dueAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Action_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MemoryRecord" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"worldId" TEXT,"title" TEXT NOT NULL,"content" TEXT NOT NULL,"classification" TEXT NOT NULL DEFAULT 'USER_STATEMENT',"source" TEXT NOT NULL DEFAULT 'USER_ENTERED',"confidence" DOUBLE PRECISION,"status" TEXT NOT NULL DEFAULT 'active',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MemoryRecord_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MemoryEmbedding" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"memoryId" TEXT NOT NULL,"embedding" vector(1536) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MemoryEmbedding_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ChatMessage" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"role" TEXT NOT NULL,"content" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChatMessage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditEvent" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"event" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "PersonalProfile_userId_key" ON "PersonalProfile"("userId");
CREATE UNIQUE INDEX "ProfileVersion_profileId_version_key" ON "ProfileVersion"("profileId","version");
CREATE UNIQUE INDEX "World_userId_slug_key" ON "World"("userId","slug");
CREATE INDEX "World_userId_idx" ON "World"("userId");
CREATE INDEX "Action_userId_completedAt_idx" ON "Action"("userId","completedAt");
CREATE INDEX "MemoryRecord_userId_status_createdAt_idx" ON "MemoryRecord"("userId","status","createdAt");
CREATE UNIQUE INDEX "MemoryEmbedding_memoryId_key" ON "MemoryEmbedding"("memoryId");
CREATE INDEX "MemoryEmbedding_userId_idx" ON "MemoryEmbedding"("userId");
CREATE INDEX "MemoryEmbedding_embedding_hnsw_idx" ON "MemoryEmbedding" USING hnsw ("embedding" vector_cosine_ops);
CREATE INDEX "ChatMessage_userId_createdAt_idx" ON "ChatMessage"("userId","createdAt");
CREATE INDEX "AuditEvent_userId_createdAt_idx" ON "AuditEvent"("userId","createdAt");
ALTER TABLE "PersonalProfile" ADD CONSTRAINT "PersonalProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProfileVersion" ADD CONSTRAINT "ProfileVersion_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "PersonalProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "World" ADD CONSTRAINT "World_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Action" ADD CONSTRAINT "Action_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Action" ADD CONSTRAINT "Action_worldId_fkey" FOREIGN KEY ("worldId") REFERENCES "World"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "MemoryRecord" ADD CONSTRAINT "MemoryRecord_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MemoryRecord" ADD CONSTRAINT "MemoryRecord_worldId_fkey" FOREIGN KEY ("worldId") REFERENCES "World"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "MemoryEmbedding" ADD CONSTRAINT "MemoryEmbedding_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MemoryEmbedding" ADD CONSTRAINT "MemoryEmbedding_memoryId_fkey" FOREIGN KEY ("memoryId") REFERENCES "MemoryRecord"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ChatMessage" ADD CONSTRAINT "ChatMessage_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditEvent" ADD CONSTRAINT "AuditEvent_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
